using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
namespace DoomSNESed {
    public static class WavImport {
        static int Predictor(int filter,int old,int older){return filter==1?old+(-old>>4):filter==2?2*old+((3*-old)>>5)-older+(older>>4):filter==3?2*old+((13*-old)>>6)-older+((3*older)>>4):0;}
        static int DecodeValue(int nibble,int range,int filter,int old,int older){int value=(range<=12?((nibble<<range)>>1):nibble<0?-2048:0)+Predictor(filter,old,older);value=Math.Max(-32768,Math.Min(32767,value));return ((short)((value&32767)<<1))>>1;}
        public static byte[] Encode(short[] pcm,bool loop){int blocks=(pcm.Length+15)/16;Bin.Require(blocks>0,"Empty sound sample.");var bytes=new byte[3+blocks*9];bytes[2]=64;int old=0,older=0;for(int block=0;block<blocks;block++){long bestError=long.MaxValue;int bestOld=0,bestOlder=0,bestHeader=0;byte[] best=null;for(int filter=0;filter<(block==0?1:4);filter++)for(int range=0;range<=12;range++){int last=old,previous=older;long error=0;var candidate=new byte[8];for(int i=0;i<16;i++){int sample=block*16+i<pcm.Length?pcm[block*16+i]/2:0,prediction=Predictor(filter,last,previous);int nibble=Math.Max(-8,Math.Min(7,(int)Math.Round((sample-prediction)*2.0/(1<<range))));int value=DecodeValue(nibble,range,filter,last,previous);long delta=sample-value;error+=delta*delta;candidate[i/2]|=(byte)((nibble&15)<<((i&1)==0?4:0));previous=last;last=value;}if(error<bestError){bestError=error;best=candidate;bestOld=last;bestOlder=previous;bestHeader=(range<<4)|(filter<<2);}}int p=3+block*9;bytes[p]=(byte)(bestHeader|(block==blocks-1?(loop?3:1):0));Buffer.BlockCopy(best,0,bytes,p+1,8);old=bestOld;older=bestOlder;}return bytes;}
        public static short[] Decode(byte[] bytes){Bin.Require(bytes.Length>=12&&(bytes.Length-3)%9==0,"Invalid native BRR sample.");var pcm=new List<short>();int old=0,older=0;for(int p=3;p+9<=bytes.Length;p+=9){int header=bytes[p],range=header>>4,filter=(header>>2)&3;for(int i=0;i<16;i++){int nibble=(bytes[p+1+i/2]>>((i&1)==0?4:0))&15;if(nibble>7)nibble-=16;int value=DecodeValue(nibble,range,filter,old,older);pcm.Add((short)(value*2));older=old;old=value;}if((header&1)!=0)break;}return pcm.ToArray();}
        static double[] Read(string path,int targetRate){Bin.Require(new FileInfo(path).Length<=64*1024*1024,"WAV exceeds 64 MiB.");byte[] b=File.ReadAllBytes(path);Bin.Require(b.Length>=44&&b.Length<=64*1024*1024&&Encoding.ASCII.GetString(b,0,4)=="RIFF"&&Encoding.ASCII.GetString(b,8,4)=="WAVE","Choose a RIFF WAV file up to 64 MiB.");int format=0,channels=0,rate=0,bits=0,align=0,data=-1,length=0;for(int p=12;p+8<=b.Length;){int n=BitConverter.ToInt32(b,p+4);Bin.Require(n>=0&&n<=b.Length-p-8,"Invalid WAV chunk.");string id=Encoding.ASCII.GetString(b,p,4);int start=p+8;if(id=="fmt "){Bin.Require(n>=16,"Invalid WAV format.");format=Bin.U16(b,start);channels=Bin.U16(b,start+2);rate=BitConverter.ToInt32(b,start+4);align=Bin.U16(b,start+12);bits=Bin.U16(b,start+14);if(format==65534&&n>=40)format=Bin.U16(b,start+24);}else if(id=="data"&&data<0){data=start;length=n;}p=start+n+(n&1);}Bin.Require((format==1&&(bits==8||bits==16||bits==24||bits==32)||format==3&&bits==32)&&channels>=1&&channels<=8&&rate>=4000&&rate<=192000&&align==channels*(bits/8)&&data>=0&&length>=align&&length%align==0,"WAV must be PCM 8/16/24/32-bit or 32-bit float, with 1..8 channels.");int frames=length/align;Bin.Require(frames/(double)rate<=120,"WAV exceeds two minutes; trim it before importing.");var mono=new double[frames];for(int i=0;i<frames;i++){double sum=0;for(int c=0;c<channels;c++){int p=data+i*align+c*(bits/8);double value;if(format==3)value=BitConverter.ToSingle(b,p);else if(bits==8)value=(b[p]-128)/128.0;else if(bits==16)value=(short)Bin.U16(b,p)/32768.0;else if(bits==24){int sample=(b[p]|b[p+1]<<8|b[p+2]<<16);if((sample&0x800000)!=0)sample|=unchecked((int)0xff000000);value=sample/8388608.0;}else value=BitConverter.ToInt32(b,p)/2147483648.0;Bin.Require(!double.IsNaN(value)&&!double.IsInfinity(value),"WAV contains invalid floating-point samples.");sum+=Math.Max(-1,Math.Min(1,value));}mono[i]=sum/channels;}int target=Math.Max(1,(int)Math.Round(frames*(double)targetRate/rate));var output=new double[target];double ratio=rate/(double)targetRate;for(int i=0;i<target;i++){double position=i*ratio,sum=0,weight=0;int center=(int)position;for(int j=-16;j<=16;j++){int source=center+j;if(source<0||source>=frames)continue;double t=(source-position)*Math.Min(1,1/ratio),sinc=Math.Abs(t)<1e-9?1:Math.Sin(Math.PI*t)/(Math.PI*t),window=.5+.5*Math.Cos(Math.PI*(source-position)/17);double w=sinc*window;sum+=mono[source]*w;weight+=w;}output[i]=Math.Abs(weight)<1e-9?0:sum/weight;}return output;}
        public static SoundReplacement Convert(string path,NativeSound slot,bool trim,bool normalize,bool fit,bool loop,int targetRate=11025){Bin.Require(targetRate>=1000&&targetRate<=128000,"Invalid target playback rate.");double[] pcm=Read(path,targetRate);int original=pcm.Length,start=0,end=pcm.Length;if(trim){while(start<end&&Math.Abs(pcm[start])<.002)start++;while(end>start&&Math.Abs(pcm[end-1])<.002)end--;}Bin.Require(end>start,"The WAV contains only silence.");int capacity=slot.Turbo?3321:slot.Bytes,maximum=((capacity-3)/9)*16;bool shortened=end-start>maximum;if(shortened){Bin.Require(fit,"This sample needs "+(3+((end-start+15)/16)*9)+" BRR bytes; the native slot allows "+capacity+". Trim it or enable Fit duration.");end=start+maximum;}double peak=pcm.Skip(start).Take(end-start).Max(v=>Math.Abs(v)),gain=normalize&&peak>0?.85/peak:1;var data=new short[end-start];for(int i=0;i<data.Length;i++){double value=pcm[start+i]*gain;if(!loop&&i>=data.Length-32)value*=Math.Max(0,(data.Length-1-i)/31.0);data[i]=(short)Math.Max(-30000,Math.Min(30000,(int)Math.Round(value*32767)));}byte[] encoded=Encode(data,loop);return new SoundReplacement{Wave=slot.Wave,Name=Path.GetFileName(path),Data=encoded,Loop=loop,Rate=targetRate,Report=targetRate+" Hz mono, adaptive BRR filters; "+encoded.Length+" / "+capacity+" B; "+(data.Length/(double)targetRate).ToString("0.000")+" s. "+(trim?"Silence trimmed. ":"")+(normalize?"Peak normalized. ":"")+(shortened?"Tail truncated to fit native SPC capacity. ":"")+(loop?"Loops from the beginning.":"One-shot.")+" Source: "+original+" resampled frames."};}
        public static byte[] WaveFile(short[] pcm,int rate){using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream)){writer.Write(Encoding.ASCII.GetBytes("RIFF"));writer.Write(36+pcm.Length*2);writer.Write(Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(rate);writer.Write(rate*2);writer.Write((short)2);writer.Write((short)16);writer.Write(Encoding.ASCII.GetBytes("data"));writer.Write(pcm.Length*2);foreach(short sample in pcm)writer.Write(sample);return stream.ToArray();}}
    }
}
